INSERT INTO quest (name, min_Delta, max_Solves, message) VALUES
  ('SunkenLyceumShards', 0, -1, 'Lyceum Record Shards given to Aldra Venn.'),
  ('SunkenLyceumBroodSeal', 0, 1, 'Aldra Venn opened the Brood Seal of the Sunken Lyceum for you.'),
  ('SunkenLyceumWellspring', 0, 1, 'Aldra Venn attuned you to the Wellspring Gate with the First Brand.'),
  ('UnboundQueenRewarded', 0, 1, 'Brought the crown of the Unbound Queen to Aldra Venn.'),
  ('UnboundQueenSlain', 72000, -1, 'Helped slay the Unbound Queen.'),
  ('UnboundQueenZefirCharm', 72000, -1, 'Aldra Venn gave you a Zefir Charm for a crown (once per 20 hours).'),
  ('UnboundQueenCrownTaken', 72000, -1, 'Took a crown of the Unbound Queen (one per 20 hours, her respawn).'),
  ('FirstBrandTaken', 1800, -1, 'Took a First Brand (one per 30 minutes, the First Branded''s respawn).'),
  ('FirstBrandedFlare', 0, 1, 'The First Branded''s glyphs have flared (its own registry).'),
  ('UnboundQueenCall1', 0, 1, 'The Unbound Queen''s first brood call (her own registry).'),
  ('UnboundQueenCall2', 0, 1, 'The Unbound Queen''s second brood call (her own registry).'),
  ('UnboundQueenCall3', 0, 1, 'The Unbound Queen''s third brood call (her own registry).'),
  ('UnboundQueenCall4', 0, 1, 'The Unbound Queen''s last brood call (her own registry).');
