INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 81, 0, 1, 'UnboundQueenCall4');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, p_Script) VALUES (@e, 1, 7, 0, 1, 63);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 17, 0, 1, 'The Unbound Queen rears and shrieks, and the brood answers from the walls!');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 3, 72, 0, 1);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900803, 3, 1.0, NULL, NULL, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 22, 0, 1, 'UnboundQueenSlain');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 17, 0, 1, 'The Unbound Queen''s clutch goes dark, and a silence spreads out through the hive like a held breath.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 17, 0, 1, '%tn has slain the Unbound Queen!');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 7, 1.0, NULL, NULL, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'SunkenLyceumWellspring');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'SunkenLyceumWellspring', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Wellspring Gate knows the First Brand on you. It runs down the old well-shaft from the Branding Pit into the great hall of the hive. She is there, and she is awake. Bring me her crown.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'SunkenLyceumWellspring', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 21, 0, 1, 'SunkenLyceumBroodSeal');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'SunkenLyceumBroodSeal', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Brood Seal will let you through now. The brood broke through beneath it into the Breached Hive, and they nest there beside the old Olthoi. The Empyreans kept the first Olthoi they ever branded in a pit at its heart, and the records say it is still there.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Kill it and cut the First Brand from its carapace. That glyph was the key to the well, and it still is.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'SunkenLyceumBroodSeal', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'My grandmother stirred the soup pots for the Olthoi before Elysa set her free. She said when the Queen died the whole hive went mad at once. Not these. These are clever still.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'This was an Empyrean lyceum. They studied the Olthoi here, and I think they kept something below. The records are on crystal shards. The scholars kept them in record cases in the halls down the stair, and the brood has dragged more of them into the hive like treasure.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'Bring me three Lyceum Record Shards and I will find the ward that opens the Brood Seal.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 6, 1.0, 900811, NULL, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'SunkenLyceumBroodSeal@Shard');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'SunkenLyceumBroodSeal@Shard', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 21, 0, 1, 'SunkenLyceumWellspring');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'SunkenLyceumBroodSeal@Shard', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, min, max) VALUES (@e, 0, 30, 0, 1, 'SunkenLyceumShards', 2, 999);
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'SunkenLyceumShards', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'Three. Listen: ''Year six hundred before. The flyers came through the fog with two larvae, not one. The first escaped us. The second we caught.''');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, '''We have bound her in the well-chamber and we feed her from the Wellspring. Her brood will bear our glyphs. Her brood will obey.'' There is no entry after the Sundering.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 31, 0, 1, 'SunkenLyceumShards');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 22, 0, 1, 'SunkenLyceumBroodSeal');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, percent, min_64, max_64) VALUES (@e, 4, 49, 0, 1, 0.05, 0, 30000000);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 5, 10, 1, 1, 'The ward is written here too. The Brood Seal in the Binding Hall will open for you now, and beyond it is the hive.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'SunkenLyceumShards', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message, amount) VALUES (@e, 0, 33, 0, 1, 'SunkenLyceumShards', 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'A page of the Lyceum''s day-book. Bring me more; three should give me the whole of it.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 6, 1.0, 900812, NULL, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'SunkenLyceumWellspring@Brand');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'SunkenLyceumWellspring@Brand', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The Wellspring Gate knows the First Brand on you. It runs down the old well-shaft from the Branding Pit into the great hall of the hive. She is there, and she is awake. Bring me her crown.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'SunkenLyceumWellspring@Brand', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The First Brand. Feel how warm it still is. They burned this into the first of her children six hundred years ago, to make it obey, and it never has.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 22, 0, 1, 'SunkenLyceumWellspring');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, percent, min_64, max_64) VALUES (@e, 2, 49, 0, 1, 0.08, 0, 60000000);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 10, 1, 1, 'The Wellspring Gate in the Branding Pit will know its mark on you now. The Empyreans called her the Bound Queen. When the Harbinger drank the world''s mana, the well ran dry and her bindings broke.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 6, 1.0, 900813, NULL, NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent) VALUES (@e, 0, 12, 0, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 21, 0, 1, 'UnboundQueenRewarded');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'UnboundQueenRewarded', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, weenie_Class_Id, stack_Size) VALUES (@e, 0, 74, 0, 1, 900813, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Another crown? Then she has grown a new one, or there was more than one of her. Either way, thank you.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, percent, min_64, max_64) VALUES (@e, 2, 49, 0, 1, 0.05, 0, 100000000);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 21, 0, 1, 'UnboundQueenZefirCharm');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'UnboundQueenRewarded', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, weenie_Class_Id, stack_Size) VALUES (@e, 0, 74, 0, 1, 900813, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Her crown. So she was real, and she is dead, and the Empyreans'' last experiment is finished.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'The queens on the island stopped hatching the year the well ran dry. I think her song reached them first. Perhaps now it will be quiet down there.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 22, 0, 1, 'UnboundQueenRewarded');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, amount) VALUES (@e, 4, 34, 0, 1, 780);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, weenie_Class_Id, stack_Size) VALUES (@e, 5, 3, 0, 1, 900814, 1);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, percent, min_64, max_64) VALUES (@e, 6, 49, 0, 1, 0.15, 0, 250000000);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 7, 10, 1, 1, 'Take this. The bronze on its rim came off her bindings. It still remembers how to hold something back.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 8, 21, 0, 1, 'UnboundQueenZefirCharm');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 12, 1.0, NULL, 'UnboundQueenZefirCharm', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 1, 1, 'The crystals in my cases are quiet again. Bring me a crown another day and perhaps another will wake.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 13, 1.0, NULL, 'UnboundQueenZefirCharm', NULL, NULL);
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 22, 0, 1, 'UnboundQueenZefirCharm');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Listen. One of the old crystals in my record cases has started to sing. The scholars here kept zefirs bound in crystal, small ones, for company through the long nights of study.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'Her death has woken this one. Take it. Use it and the zefir will come out and follow you, and use it again to send it home.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 67, 0, 1, 'UnboundQueenZefirRoll');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest, min_Health, max_Health) VALUES (900816, 32, 0.1111, NULL, 'UnboundQueenZefirRoll', NULL, NULL);
